const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tblQkG1DeczNyWsyM';
const MENU_TABLE_ID = 'tbltYZZMUsQg5rxPC';
const MENU_CACHE_TTL = 30 * 60 * 1000;

const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') args = JSON.parse(args);

const callId = body?.message?.call?.id || '';
const callerIdPhone = body?.message?.call?.customer?.number || '';

const customerName = args.customerName || 'Unknown';
const location = args.location || '';
const language = args.language || 'en';
const items = args.items || [];
const pickupTime = args.pickupTime || 'ASAP';

function normalizePhone(raw) {
  if (!raw) return raw;
  let p = raw.replace(/[^\d+]/g, '');
  if (p.startsWith('+')) return p;
  if (p.length === 10) return '+1' + p;
  if (p.length === 11 && p.startsWith('1')) return '+' + p;
  return '+' + p;
}
const contactPhone = normalizePhone(args.customerPhone || callerIdPhone);

// Menu cache
const cache = $getWorkflowStaticData('global');
const now = Date.now();
let menu = cache.menu;
if (!menu || (now - menu.ts) > MENU_CACHE_TTL) {
  let records = [];
  let offset;
  do {
    const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + MENU_TABLE_ID +
      '?fields[]=Item%20Name&fields[]=Price&fields[]=Price%20West%20Dearborn&pageSize=100&filterByFormula=%7BAvailable%7D%3DTRUE()' +
      (offset ? '&offset=' + offset : '');
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
    records = records.concat(res.records || []);
    offset = res.offset;
  } while (offset);
  menu = { ts: now, prices: records.map(r => ({ name: r.fields['Item Name'] || '', price: Number(r.fields['Price']) || 0, priceWD: r.fields['Price West Dearborn'] != null ? Number(r.fields['Price West Dearborn']) : null })) };
  cache.menu = menu;
}

function normalize(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\b(smoothie|wrap|bowl|salad|juice|burrito)\b/g, '').replace(/\s+/g, ' ').trim();
}
function findPrice(name, menuItemId) {
  const useWD = /west/i.test(location || '');
  const pick = m => (useWD && m.priceWD != null) ? m.priceWD : m.price;
  const candidates = [name, menuItemId].filter(Boolean).map(normalize).filter(Boolean);
  for (const c of candidates) {
    const exact = menu.prices.find(m => normalize(m.name) === c);
    if (exact) return pick(exact);
  }
  for (const c of candidates) {
    const partial = menu.prices.find(m => { const mn = normalize(m.name); return mn && (mn.includes(c) || c.includes(mn)); });
    if (partial) return pick(partial);
  }
  return null;
}

let total = 0;
const itemsText = items.map(i => {
  const qty = i.quantity || 1;
  let line = qty + 'x ' + i.name;
  const extras = [];
  if (i.notes) extras.push(i.notes);
  if (i.modifiers && i.modifiers.length) extras.push(i.modifiers.join(', '));
  if (extras.length) line += ' (' + extras.join(', ') + ')';
  const price = (typeof i.price === 'number') ? i.price : findPrice(i.name, i.menuItemId);
  if (price != null) { total += price * qty; line += ' - $' + price.toFixed(2); }
  return line;
}).join('\n');

const estimatedTotal = Math.round(total * 100) / 100;

// Ticket ID: fast read from Airtable (single record)
let ticketId = (cache.lastTicket || 1000) + 1;
try {
  const tRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID +
      '?maxRecords=1&sort%5B0%5D%5Bfield%5D=Ticket%20ID&sort%5B0%5D%5Bdirection%5D=desc&fields%5B%5D=Ticket%20ID',
    headers: { Authorization: 'Bearer ' + PAT }
  });
  const top = tRes.records?.[0];
  const topTicket = top?.fields['Ticket ID'];
  if (typeof topTicket === 'number' && topTicket > 0) ticketId = topTicket + 1;
} catch (e) {}
cache.lastTicket = ticketId;

// Respond to Vapi immediately — Airtable write + SMS happen in the next node
return [{
  json: {
    // Vapi tool response
    results: [{
      toolCallId,
      result: '[ORDER_PLACED] ticket=' + ticketId + ' | total=$' + estimatedTotal.toFixed(2) + ' | name=' + customerName + ' | pickup=' + pickupTime
    }],
    // Passed to next node for async save
    _order: {
      customerName, contactPhone, location, language, items, pickupTime,
      callId, ticketId, estimatedTotal, itemsText
    }
  }
}];

const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tblQkG1DeczNyWsyM';
const TWILIO_SID = 'TWILIO_ACCOUNT_SID_REDACTED';
const TWILIO_AUTH = 'TWILIO_AUTH_TOKEN_REDACTED';
const TWILIO_FROM = '+13136311176';
const TWILIO_TO_STAFF = '';

const data = $input.first().json._order;
if (!data) return [{ json: { skipped: true, reason: 'no _order data' } }];

const { customerName, contactPhone, location, language, items, pickupTime,
        callId, ticketId, estimatedTotal, itemsText } = data;

const errors = [];

// ── 1. Write to Airtable ─────────────────────────────────────────────────
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID,
    headers: { Authorization: 'Bearer ' + PAT, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      records: [{
        fields: {
          'Caller Name': customerName,
          'Order Items': itemsText,
          'Location': location,
          'Phone': contactPhone,
          'Total': estimatedTotal,
          'Language': language,
          'Call ID': callId,
          'Timestamp': new Date().toISOString(),
          'Raw Order JSON': JSON.stringify(items, null, 2),
          'Order Status': 'New',
          'Ticket ID': ticketId,
          'Pickup Time': pickupTime
        }
      }]
    })
  });
} catch (e) {
  errors.push('airtable: ' + e.message);
}

// ── Helper: send Twilio SMS (logs full response for debugging) ────────────
async function sendSMS(to, body) {
  const isUSCanada = to.startsWith('+1');
  if (!isUSCanada) {
    return { skipped: true, reason: 'international — Twilio US number cannot deliver to ' + to + '. Enable Geo Permissions at console.twilio.com > Messaging > Settings > Geo Permissions.' };
  }
  const b64auth = btoa(TWILIO_SID + ':' + TWILIO_AUTH);
  const formBody = 'To=' + encodeURIComponent(to) + '&From=' + encodeURIComponent(TWILIO_FROM) + '&Body=' + encodeURIComponent(body);
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.twilio.com/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
    headers: { Authorization: 'Basic ' + b64auth, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: formBody
  });
  return {
    sid: res.sid,
    status: res.status,
    error_code: res.error_code || null,
    error_message: res.error_message || null,
    to: res.to,
    from: res.from
  };
}

// ── 2. SMS to customer — now includes order items ─────────────────────────
let customerSmsResult = { skipped: true, reason: 'no phone' };
if (contactPhone) {
  try {
    // itemsText looks like: "1x Chicken Caesar Wrap (Spinach tortilla) - $11.95\n1x Mango Refresher - $5.50"
    // Compact it to a single readable line for SMS, keep prices for customer fact-check.
    const itemsLine = (itemsText || '').split('\n').filter(Boolean).join('; ');
    const msg = 'Beyond Juicery: Order #' + ticketId + ' received! Items: ' + itemsLine + '. Pickup: ' + pickupTime + ". We'll text you when it's ready.";
    customerSmsResult = await sendSMS(contactPhone, msg);
  } catch (e) {
    customerSmsResult = { error: e.message };
    errors.push('customer_sms: ' + e.message);
  }
}

// ── 3. SMS to staff ───────────────────────────────────────────────────────
let staffSmsResult = { skipped: true, reason: 'TWILIO_TO_STAFF not configured' };
if (TWILIO_TO_STAFF) {
  try {
    const msg = 'New order #' + ticketId + ': ' + customerName + '\n' + itemsText + '\nTotal: $' + estimatedTotal.toFixed(2) + '\nPickup: ' + pickupTime;
    staffSmsResult = await sendSMS(TWILIO_TO_STAFF, msg);
  } catch (e) {
    staffSmsResult = { error: e.message };
    errors.push('staff_sms: ' + e.message);
  }
}

return [{ json: { saved: true, ticketId, customerSmsResult, staffSmsResult, errors } }];
